70	/**
71	 * Negotiates SASL for DataTransferProtocol on behalf of a client.  There are
72	 * two possible supported variants of SASL negotiation: either a general-purpose
73	 * negotiation supporting any quality of protection, or a specialized
74	 * negotiation that enforces privacy as the quality of protection using a
75	 * cryptographically strong encryption key.
76	 *
77	 * This class is used in both the HDFS client and the DataNode.  The DataNode
78	 * needs it, because it acts as a client to other DataNodes during write
79	 * pipelines and block transfers.
80	 */
81	@InterfaceAudience.Private
82	public class SaslDataTransferClient {
83	
84	  private static final Logger LOG = LoggerFactory.getLogger(
85	      SaslDataTransferClient.class);
86	
87	  private final Configuration conf;
88	  private final AtomicBoolean fallbackToSimpleAuth;
89	  private final SaslPropertiesResolver saslPropsResolver;
90	  private final TrustedChannelResolver trustedChannelResolver;
91	
92	  // Store the most recent successfully negotiated QOP,
93	  // for testing purpose only
94	  private String targetQOP;
95	
96	  /**
97	   * Creates a new SaslDataTransferClient.  This constructor is used in cases
98	   * where it is not relevant to track if a secure client did a fallback to
99	   * simple auth.  For intra-cluster connections between data nodes in the same
100	   * cluster, we can assume that all run under the same security configuration.
101	   *
102	   * @param conf the configuration
103	   * @param saslPropsResolver for determining properties of SASL negotiation
104	   * @param trustedChannelResolver for identifying trusted connections that do
105	   *   not require SASL negotiation
106	   */
107	  public SaslDataTransferClient(Configuration conf,
108	      SaslPropertiesResolver saslPropsResolver,
109	      TrustedChannelResolver trustedChannelResolver) {
110	    this(conf, saslPropsResolver, trustedChannelResolver, null);
111	  }
112	
113	  /**
114	   * Creates a new SaslDataTransferClient.
115	   *
116	   * @param conf the configuration
117	   * @param saslPropsResolver for determining properties of SASL negotiation
118	   * @param trustedChannelResolver for identifying trusted connections that do
119	   *   not require SASL negotiation
120	   * @param fallbackToSimpleAuth checked on each attempt at general SASL
121	   *   handshake, if true forces use of simple auth
122	   */
123	  public SaslDataTransferClient(Configuration conf,
124	      SaslPropertiesResolver saslPropsResolver,
125	      TrustedChannelResolver trustedChannelResolver,
126	      AtomicBoolean fallbackToSimpleAuth) {
127	    this.conf = conf;
128	    this.fallbackToSimpleAuth = fallbackToSimpleAuth;
129	    this.saslPropsResolver = saslPropsResolver;
130	    this.trustedChannelResolver = trustedChannelResolver;
131	  }
132	
133	  /**
134	   * Sends client SASL negotiation for a newly allocated socket if required.
135	   *
136	   * @param socket connection socket
137	   * @param underlyingOut connection output stream
138	   * @param underlyingIn connection input stream
139	   * @param encryptionKeyFactory for creation of an encryption key
140	   * @param accessToken connection block access token
141	   * @param datanodeId ID of destination DataNode
142	   * @return new pair of streams, wrapped after SASL negotiation
143	   * @throws IOException for any error
144	   */
145	  public IOStreamPair newSocketSend(Socket socket, OutputStream underlyingOut,
146	      InputStream underlyingIn, DataEncryptionKeyFactory encryptionKeyFactory,
147	      Token<BlockTokenIdentifier> accessToken, DatanodeID datanodeId)
148	      throws IOException {
149	    // The encryption key factory only returns a key if encryption is enabled.
150	    DataEncryptionKey encryptionKey = !trustedChannelResolver.isTrusted() ?
151	        encryptionKeyFactory.newDataEncryptionKey() : null;
152	    IOStreamPair ios = send(socket.getInetAddress(), underlyingOut,
153	        underlyingIn, encryptionKey, accessToken, datanodeId, null);
154	    return ios != null ? ios : new IOStreamPair(underlyingIn, underlyingOut);
155	  }
156	
157	  /**
158	   * Sends client SASL negotiation for a peer if required.
159	   *
160	   * @param peer connection peer
161	   * @param encryptionKeyFactory for creation of an encryption key
162	   * @param accessToken connection block access token
163	   * @param datanodeId ID of destination DataNode
164	   * @return new pair of streams, wrapped after SASL negotiation
165	   * @throws IOException for any error
166	   */
167	  public Peer peerSend(Peer peer, DataEncryptionKeyFactory encryptionKeyFactory,
168	      Token<BlockTokenIdentifier> accessToken, DatanodeID datanodeId)
169	      throws IOException {
170	    IOStreamPair ios = checkTrustAndSend(getPeerAddress(peer),
171	        peer.getOutputStream(), peer.getInputStream(), encryptionKeyFactory,
172	        accessToken, datanodeId, null);
173	    // TODO: Consider renaming EncryptedPeer to SaslPeer.
174	    return ios != null ? new EncryptedPeer(peer, ios) : peer;
175	  }
