177	  /**
178	   * Sends client SASL negotiation for a socket if required.
179	   *
180	   * @param socket connection socket
181	   * @param underlyingOut connection output stream
182	   * @param underlyingIn connection input stream
183	   * @param encryptionKeyFactory for creation of an encryption key
184	   * @param accessToken connection block access token
185	   * @param datanodeId ID of destination DataNode
186	   * @return new pair of streams, wrapped after SASL negotiation
187	   * @throws IOException for any error
188	   */
189	  public IOStreamPair socketSend(Socket socket, OutputStream underlyingOut,
190	      InputStream underlyingIn, DataEncryptionKeyFactory encryptionKeyFactory,
191	      Token<BlockTokenIdentifier> accessToken, DatanodeID datanodeId)
192	      throws IOException {
193	    return socketSend(socket, underlyingOut, underlyingIn, encryptionKeyFactory,
194	        accessToken, datanodeId, null);
195	  }
