197	  public IOStreamPair socketSend(
198	      Socket socket, OutputStream underlyingOut, InputStream underlyingIn,
199	      DataEncryptionKeyFactory encryptionKeyFactory,
200	      Token<BlockTokenIdentifier> accessToken, DatanodeID datanodeId,
201	      SecretKey secretKey)
202	      throws IOException {
203	    IOStreamPair ios = checkTrustAndSend(socket.getInetAddress(), underlyingOut,
204	        underlyingIn, encryptionKeyFactory, accessToken, datanodeId,
205	        secretKey);
206	    return ios != null ? ios : new IOStreamPair(underlyingIn, underlyingOut);
207	  }
