209	  /**
210	   * Checks if an address is already trusted and then sends client SASL
211	   * negotiation if required.
212	   *
213	   * @param addr connection address
214	   * @param underlyingOut connection output stream
215	   * @param underlyingIn connection input stream
216	   * @param encryptionKeyFactory for creation of an encryption key
217	   * @param accessToken connection block access token
218	   * @param datanodeId ID of destination DataNode
219	   * @return new pair of streams, wrapped after SASL negotiation
220	   * @throws IOException for any error
221	   */
222	  private IOStreamPair checkTrustAndSend(
223	      InetAddress addr, OutputStream underlyingOut, InputStream underlyingIn,
224	      DataEncryptionKeyFactory encryptionKeyFactory,
225	      Token<BlockTokenIdentifier> accessToken, DatanodeID datanodeId,
226	      SecretKey secretKey)
227	      throws IOException {
228	    boolean localTrusted = trustedChannelResolver.isTrusted();
229	    boolean remoteTrusted = trustedChannelResolver.isTrusted(addr);
230	    LOG.debug("SASL encryption trust check: localHostTrusted = {}, "
231	        + "remoteHostTrusted = {}", localTrusted, remoteTrusted);
232	    if (!localTrusted || !remoteTrusted) {
233	      // The encryption key factory only returns a key if encryption is enabled.
234	      DataEncryptionKey encryptionKey =
235	          encryptionKeyFactory.newDataEncryptionKey();
236	      return send(addr, underlyingOut, underlyingIn, encryptionKey, accessToken,
237	          datanodeId, secretKey);
238	    } else {
239	      LOG.debug(
240	          "SASL client skipping handshake on trusted connection for addr = {}, "
241	              + "datanodeId = {}", addr, datanodeId);
242	      return null;
243	    }
244	  }
245	
246	  /**
247	   * Sends client SASL negotiation if required.  Determines the correct type of
248	   * SASL handshake based on configuration.
249	   *
250	   * @param addr connection address
251	   * @param underlyingOut connection output stream
252	   * @param underlyingIn connection input stream
253	   * @param encryptionKey for an encrypted SASL handshake
254	   * @param accessToken connection block access token
255	   * @param datanodeId ID of destination DataNode
256	   * @return new pair of streams, wrapped after SASL negotiation
257	   * @throws IOException for any error
258	   */
259	  private IOStreamPair send(InetAddress addr, OutputStream underlyingOut,
260	      InputStream underlyingIn, DataEncryptionKey encryptionKey,
261	      Token<BlockTokenIdentifier> accessToken, DatanodeID datanodeId,
262	      SecretKey secretKey)
263	      throws IOException {
264	    if (encryptionKey != null) {
265	      LOG.debug("SASL client doing encrypted handshake for addr = {}, "
266	          + "datanodeId = {}", addr, datanodeId);
267	      return getEncryptedStreams(addr, underlyingOut, underlyingIn,
268	          encryptionKey, accessToken, secretKey);
269	    } else if (!UserGroupInformation.isSecurityEnabled()) {
270	      LOG.debug("SASL client skipping handshake in unsecured configuration for "
271	          + "addr = {}, datanodeId = {}", addr, datanodeId);
272	      return null;
273	    } else if (SecurityUtil.isPrivilegedPort(datanodeId.getXferPort())) {
274	      LOG.debug(
275	          "SASL client skipping handshake in secured configuration with "
276	              + "privileged port for addr = {}, datanodeId = {}",
277	          addr, datanodeId);
278	      return null;
279	    } else if (fallbackToSimpleAuth != null && fallbackToSimpleAuth.get()) {
280	      LOG.debug(
281	          "SASL client skipping handshake in secured configuration with "
282	              + "unsecured cluster for addr = {}, datanodeId = {}",
283	          addr, datanodeId);
284	      return null;
285	    } else if (saslPropsResolver != null) {
286	      LOG.debug(
287	          "SASL client doing general handshake for addr = {}, datanodeId = {}",
288	          addr, datanodeId);
289	      return getSaslStreams(addr, underlyingOut, underlyingIn,
290	          accessToken, secretKey);
291	    } else {
292	      // It's a secured cluster using non-privileged ports, but no SASL.  The
293	      // only way this can happen is if the DataNode has
294	      // ignore.secure.ports.for.testing configured so this is a rare edge case.
295	      LOG.debug("SASL client skipping handshake in secured configuration with "
296	              + "no SASL protection configured for addr = {}, datanodeId = {}",
297	          addr, datanodeId);
298	      return null;
299	    }
300	  }
301	
302	  /**
303	   * Sends client SASL negotiation for specialized encrypted handshake.
304	   *
305	   * @param addr connection address
306	   * @param underlyingOut connection output stream
307	   * @param underlyingIn connection input stream
308	   * @param encryptionKey for an encrypted SASL handshake
309	   * @return new pair of streams, wrapped after SASL negotiation
310	   * @throws IOException for any error
311	   */
312	  private IOStreamPair getEncryptedStreams(InetAddress addr,
313	      OutputStream underlyingOut, InputStream underlyingIn,
314	      DataEncryptionKey encryptionKey,
315	      Token<BlockTokenIdentifier> accessToken,
316	      SecretKey secretKey)
317	      throws IOException {
318	    Map<String, String> saslProps = createSaslPropertiesForEncryption(
319	        encryptionKey.encryptionAlgorithm);
320	    if (secretKey != null) {
321	      LOG.debug("DataNode overwriting downstream QOP" +
322	          saslProps.get(Sasl.QOP));
323	      updateToken(accessToken, secretKey, saslProps);
324	    }
325	
326	    LOG.debug("Client using encryption algorithm {}",
327	        encryptionKey.encryptionAlgorithm);
328	
329	    String userName = getUserNameFromEncryptionKey(encryptionKey);
330	    char[] password = encryptionKeyToPassword(encryptionKey.encryptionKey);
331	    CallbackHandler callbackHandler = new SaslClientCallbackHandler(userName,
332	        password);
333	    return doSaslHandshake(addr, underlyingOut, underlyingIn, userName,
334	        saslProps, callbackHandler, accessToken);
335	  }
336	
337	  /**
338	   * The SASL username for an encrypted handshake consists of the keyId,
339	   * blockPoolId, and nonce with the first two encoded as Strings, and the third
340	   * encoded using Base64. The fields are each separated by a single space.
341	   *
342	   * @param encryptionKey the encryption key to encode as a SASL username.
343	   * @return encoded username containing keyId, blockPoolId, and nonce
344	   */
345	  private static String getUserNameFromEncryptionKey(
346	      DataEncryptionKey encryptionKey) {
347	    return encryptionKey.keyId + NAME_DELIMITER +
348	        encryptionKey.blockPoolId + NAME_DELIMITER +
349	        new String(Base64.encodeBase64(encryptionKey.nonce, false),
350	            Charsets.UTF_8);
351	  }
352	
353	  /**
354	   * Sets user name and password when asked by the client-side SASL object.
355	   */
356	  private static final class SaslClientCallbackHandler
357	      implements CallbackHandler {
358	
359	    private final char[] password;
360	    private final String userName;
361	
362	    /**
363	     * Creates a new SaslClientCallbackHandler.
364	     *
365	     * @param userName SASL user name
366	     * @param password SASL password
367	     */
368	    public SaslClientCallbackHandler(String userName, char[] password) {
369	      this.password = password;
370	      this.userName = userName;
371	    }
372	
373	    @Override
374	    public void handle(Callback[] callbacks) throws IOException,
375	        UnsupportedCallbackException {
376	      NameCallback nc = null;
377	      PasswordCallback pc = null;
378	      RealmCallback rc = null;
379	      for (Callback callback : callbacks) {
380	        if (callback instanceof NameCallback) {
381	          nc = (NameCallback) callback;
382	        } else if (callback instanceof PasswordCallback) {
383	          pc = (PasswordCallback) callback;
384	        } else if (callback instanceof RealmCallback) {
385	          rc = (RealmCallback) callback;
386	        } else if (!(callback instanceof RealmChoiceCallback)) {
387	          throw new UnsupportedCallbackException(callback,
388	              "Unrecognized SASL client callback");
389	        }
390	      }
391	      if (nc != null) {
392	        nc.setName(userName);
393	      }
394	      if (pc != null) {
395	        pc.setPassword(password);
396	      }
397	      if (rc != null) {
398	        rc.setText(rc.getDefaultText());
399	      }
400	    }
401	  }
402	
403	  @VisibleForTesting
404	  public String getTargetQOP() {
405	    return targetQOP;
406	  }
407	
408	  /**
409	   * Sends client SASL negotiation for general-purpose handshake.
410	   *
411	   * @param addr connection address
412	   * @param underlyingOut connection output stream
413	   * @param underlyingIn connection input stream
414	   * @param accessToken connection block access token
415	   * @return new pair of streams, wrapped after SASL negotiation
416	   * @throws IOException for any error
417	   */
418	  private IOStreamPair getSaslStreams(InetAddress addr,
419	      OutputStream underlyingOut, InputStream underlyingIn,
420	      Token<BlockTokenIdentifier> accessToken,
421	      SecretKey secretKey)
422	      throws IOException {
423	    Map<String, String> saslProps = saslPropsResolver.getClientProperties(addr);
424	
425	    // secretKey != null only happens when this is called by DN
426	    // sending to downstream DN. If called from client, this will be null,
427	    // as there is no key for client to generate mac instance.
428	    // So that, if a different QOP is desired for inter-DN communication,
429	    // the check below will use new QOP to create a secret, which includes
430	    // the new QOP.
431	    if (secretKey != null) {
432	      String newQOP = conf
433	          .get(DFS_ENCRYPT_DATA_OVERWRITE_DOWNSTREAM_NEW_QOP_KEY);
434	      if (newQOP != null) {
435	        saslProps.put(Sasl.QOP, newQOP);
436	      }
437	      LOG.debug("DataNode overwriting downstream QOP " +
438	          saslProps.get(Sasl.QOP));
439	      updateToken(accessToken, secretKey, saslProps);
440	    }
441	    targetQOP = saslProps.get(Sasl.QOP);
442	    String userName = buildUserName(accessToken);
443	    char[] password = buildClientPassword(accessToken);
444	    CallbackHandler callbackHandler = new SaslClientCallbackHandler(userName,
445	        password);
446	    return doSaslHandshake(addr, underlyingOut, underlyingIn, userName,
447	        saslProps, callbackHandler, accessToken);
448	  }
449	
450	  private void updateToken(Token<BlockTokenIdentifier> accessToken,
451	      SecretKey secretKey, Map<String, String> saslProps)
452	      throws IOException {
453	    byte[] newSecret = saslProps.get(Sasl.QOP).getBytes(Charsets.UTF_8);
454	    BlockTokenIdentifier bkid = accessToken.decodeIdentifier();
455	    bkid.setHandshakeMsg(newSecret);
456	    byte[] bkidBytes = bkid.getBytes();
457	    accessToken.setPassword(
458	        SecretManager.createPassword(bkidBytes, secretKey));
459	    accessToken.setID(bkidBytes);
460	  }
461	
462	  /**
463	   * Builds the client's user name for the general-purpose handshake, consisting
464	   * of the base64-encoded serialized block access token identifier.  Note that
465	   * this includes only the token identifier, not the token itself, which would
466	   * include the password.  The password is a shared secret, and we must not
467	   * write it on the network during the SASL authentication exchange.
468	   *
469	   * @param blockToken for block access
470	   * @return SASL user name
471	   */
472	  private static String buildUserName(Token<BlockTokenIdentifier> blockToken) {
473	    return new String(Base64.encodeBase64(blockToken.getIdentifier(), false),
474	        Charsets.UTF_8);
475	  }
476	
477	  /**
478	   * Calculates the password on the client side for the general-purpose
479	   * handshake.  The password consists of the block access token's password.
480	   *
481	   * @param blockToken for block access
482	   * @return SASL password
483	   */
484	  private char[] buildClientPassword(Token<BlockTokenIdentifier> blockToken) {
485	    return new String(Base64.encodeBase64(blockToken.getPassword(), false),
486	        Charsets.UTF_8).toCharArray();
487	  }
488	
489	  /**
490	   * This method actually executes the client-side SASL handshake.
491	   *
492	   * @param addr connection address
493	   * @param underlyingOut connection output stream
494	   * @param underlyingIn connection input stream
495	   * @param userName SASL user name
496	   * @param saslProps properties of SASL negotiation
497	   * @param callbackHandler for responding to SASL callbacks
498	   * @return new pair of streams, wrapped after SASL negotiation
499	   * @throws IOException for any error
500	   */
501	  private IOStreamPair doSaslHandshake(InetAddress addr,
502	      OutputStream underlyingOut, InputStream underlyingIn, String userName,
503	      Map<String, String> saslProps, CallbackHandler callbackHandler,
504	      Token<BlockTokenIdentifier> accessToken) throws IOException {
505	
506	    DataOutputStream out = new DataOutputStream(underlyingOut);
507	    DataInputStream in = new DataInputStream(underlyingIn);
508	
509	    SaslParticipant sasl= SaslParticipant.createClientSaslParticipant(userName,
510	        saslProps, callbackHandler);
511	
512	    out.writeInt(SASL_TRANSFER_MAGIC_NUMBER);
513	    out.flush();
514	
515	    try {
516	      // Start of handshake - "initial response" in SASL terminology.
517	      // The handshake secret can be null, this happens when client is running
518	      // a new version but the cluster does not have this feature.
519	      // In which case there will be no encrypted secret sent from NN.
520	      BlockTokenIdentifier blockTokenIdentifier =
521	          accessToken.decodeIdentifier();
522	      if (blockTokenIdentifier != null) {
523	        byte[] handshakeSecret =
524	            accessToken.decodeIdentifier().getHandshakeMsg();
525	        if (handshakeSecret == null || handshakeSecret.length == 0) {
