360	  public ListenableFuture<Void> sendEdits(
361	      final long segmentTxId, final long firstTxnId,
362	      final int numTxns, final byte[] data) {
363	    try {
364	      reserveQueueSpace(data.length);
365	    } catch (LoggerTooFarBehindException e) {
366	      return Futures.immediateFailedFuture(e);
367	    }
368	    
369	    // When this batch is acked, we use its submission time in order
370	    // to calculate how far we are lagging.
371	    final long submitNanos = System.nanoTime();
372	    
373	    ListenableFuture<Void> ret = null;
374	    try {
375	      ret = singleThreadExecutor.submit(() -> {
376	        throwIfOutOfSync();
377	
378	        long rpcSendTimeNanos = System.nanoTime();
379	        try {
380	          getProxy().journal(createReqInfo(),
381	              segmentTxId, firstTxnId, numTxns, data);
382	        } catch (IOException e) {
383	          QuorumJournalManager.LOG.warn(
384	              "Remote journal " + IPCLoggerChannel.this + " failed to " +
385	              "write txns " + firstTxnId + "-" + (firstTxnId + numTxns - 1) +
386	              ". Will try to write to this JN again after the next " +
387	              "log roll.", e);
388	          synchronized (IPCLoggerChannel.this) {
389	            outOfSync = true;
390	          }
391	          throw e;
392	        } finally {
393	          long now = System.nanoTime();
394	          long rpcTime = TimeUnit.MICROSECONDS.convert(
395	              now - rpcSendTimeNanos, TimeUnit.NANOSECONDS);
396	          long endToEndTime = TimeUnit.MICROSECONDS.convert(
397	              now - submitNanos, TimeUnit.NANOSECONDS);
398	          metrics.addWriteEndToEndLatency(endToEndTime);
399	          metrics.addWriteRpcLatency(rpcTime);
400	          if (rpcTime / 1000 > WARN_JOURNAL_MILLIS_THRESHOLD) {
401	            QuorumJournalManager.LOG.warn(
402	                "Took " + (rpcTime / 1000) + "ms to send a batch of " +
403	                numTxns + " edits (" + data.length + " bytes) to " +
404	                "remote journal " + IPCLoggerChannel.this);
405	          }
406	        }
407	        synchronized (IPCLoggerChannel.this) {
408	          highestAckedTxId = firstTxnId + numTxns - 1;
409	          lastAckNanos = submitNanos;
410	        }
411	        return null;
412	      });
413	    } finally {
414	      if (ret == null) {
415	        // it didn't successfully get submitted,
416	        // so adjust the queue size back down.
417	        unreserveQueueSpace(data.length);
418	      } else {
419	        // It was submitted to the queue, so adjust the length
420	        // once the call completes, regardless of whether it
421	        // succeeds or fails.
422	        Futures.addCallback(ret, new FutureCallback<Void>() {
423	          @Override
424	          public void onFailure(Throwable t) {
425	            unreserveQueueSpace(data.length);
426	          }
427	
428	          @Override
429	          public void onSuccess(Void t) {
430	            unreserveQueueSpace(data.length);
431	          }
432	        }, MoreExecutors.directExecutor());
433	      }
434	    }
435	    return ret;
436	  }
